-- R5 additive migration. Existing wallet, item inventory, receipts and run pins are preserved.
SELECT set_config('foxy.forge_writer','runner-forge.1',true);
ALTER TABLE entity_parameters DISABLE TRIGGER balance_protect_history;
UPDATE entity_parameters SET text_pattern='^runner-balance[.][12]$' WHERE entity_type_id='ca5b0000-0000-5000-a000-000000000002' AND code='schema-version';
SET CONSTRAINTS ALL IMMEDIATE;
ALTER TABLE entity_parameters ENABLE TRIGGER balance_protect_history;
SET CONSTRAINTS ALL DEFERRED;
UPDATE entity_parameters SET text_pattern='^(fast_reel|long_link|piercing_tooth|return_sickle|conductor_cuffs|side_step_boots|trophy_counter|debt_clock)$' WHERE entity_type_id='ca5d0000-0000-5000-a000-000000000003' AND code='definition';
UPDATE entities SET state='active',revision=1 WHERE id='ca5f0000-0000-5000-a000-000000000002';
UPDATE entity_parameter_values SET value_reference='ca5f0000-0000-5000-a000-000000000002' WHERE entity_id='ca5b0000-0000-5000-a000-000000000004';
DO $$ DECLARE a record;obj uuid;stamp bigint; BEGIN SELECT (extract(epoch FROM value_timestamp)*1000)::bigint INTO stamp FROM entity_parameter_values v JOIN entity_parameters p ON p.id=v.parameter_id WHERE v.entity_id='ca5f0000-0000-5000-a000-000000000002' AND p.code='published-at'; FOR a IN SELECT id FROM entities WHERE entity_type_id='ca5d0000-0000-5000-a000-000000000001' AND state='active' LOOP obj:=md5('runner-forge.1:account:'||a.id::text)::uuid; INSERT INTO entities(id,entity_type_id) VALUES(obj,'ca5f0000-0000-5000-a000-000000000001'); INSERT INTO entity_parameter_values(entity_id,parameter_id,entity_type_id,data_type,is_multiple,is_unique,value_reference,reference_type_id) VALUES(obj,'8fdb5de1-7fb3-8193-e8b4-57dc200f8288','ca5f0000-0000-5000-a000-000000000001','reference',false,true,a.id,'ca5d0000-0000-5000-a000-000000000001'); INSERT INTO entity_parameter_values(entity_id,parameter_id,entity_type_id,data_type,is_multiple,is_unique,value_integer) SELECT obj,id,entity_type_id,'integer',false,false,CASE WHEN code='settled-at-ms' THEN stamp ELSE 0 END FROM entity_parameters WHERE entity_type_id='ca5f0000-0000-5000-a000-000000000001' AND code<>'owner'; UPDATE entities SET state='active',revision=1 WHERE id=obj; END LOOP; END $$;
CREATE FUNCTION forge_fence_writer() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE typ uuid; BEGIN IF TG_TABLE_NAME='profile_runs' THEN typ:='ca5d0000-0000-5000-a000-000000000002'; ELSE IF TG_OP='DELETE' THEN typ:=OLD.entity_type_id; ELSE typ:=NEW.entity_type_id; END IF; END IF; IF typ IN('ca5d0000-0000-5000-a000-000000000002','ca5d0000-0000-5000-a000-000000000003','ca5d0000-0000-5000-a000-000000000004','ca5f0000-0000-5000-a000-000000000001','ca5b0000-0000-5000-a000-000000000002','ca5b0000-0000-5000-a000-000000000003') AND current_setting('foxy.forge_writer',true) IS DISTINCT FROM 'runner-forge.1' THEN RAISE EXCEPTION 'R5 compatible wallet writer required' USING ERRCODE='23514'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER forge_fence_writer BEFORE INSERT OR UPDATE OR DELETE ON entities FOR EACH ROW EXECUTE FUNCTION forge_fence_writer();
CREATE TRIGGER forge_fence_writer BEFORE INSERT OR UPDATE OR DELETE ON entity_parameter_values FOR EACH ROW EXECUTE FUNCTION forge_fence_writer();
CREATE TRIGGER forge_fence_writer BEFORE INSERT OR UPDATE OR DELETE ON profile_runs FOR EACH ROW EXECUTE FUNCTION forge_fence_writer();
CREATE FUNCTION forge_validate_balance() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE obj uuid;schema text; BEGIN IF TG_TABLE_NAME='entities' THEN IF TG_OP='DELETE' THEN obj:=OLD.id; ELSE obj:=NEW.id; END IF; ELSE IF TG_OP='DELETE' THEN obj:=OLD.entity_id; ELSE obj:=NEW.entity_id; END IF; END IF; IF EXISTS(SELECT 1 FROM entities WHERE id=obj AND entity_type_id='ca5b0000-0000-5000-a000-000000000002' AND state='active') THEN SELECT value_text INTO schema FROM entity_parameter_values v JOIN entity_parameters p ON p.id=v.parameter_id WHERE v.entity_id=obj AND p.code='schema-version'; IF schema='runner-balance.2' THEN IF EXISTS(SELECT 1 FROM entity_parameters p WHERE p.entity_type_id='ca5b0000-0000-5000-a000-000000000002' AND p.code IN('publication-order','b-85e68addd7ab15785bf71d567cce71ee','b-c0f793930208e7b0c0a72447a13cef20','b-e00f735e596e9a3ebeca13c9dacf8166','b-511e14d69cb6a1a57cadd0dd7dd77cbf','b-3b76763d0b8c898af75bf3eb4ebdc991','b-ac42f13ce036302acdecf7066ff2bd7c','b-9c4fd80c3b3a24c99eb7841928903cfb','b-8c3a41b593d070809feb74df206a4134','b-8a9cbd124b2d1f97ed6fa505af229a17','b-59e3571c09c659912e5854b94aa32bf7','b-10f3eb95d20377431047c08ae546c0c1','b-a0ad7fcffe8ac9a5de33b52d40be19cf','b-9464ebf5408e4af7e53159383a6e4f95','b-2a7a23d3a69c1410cf8492cfac7420f8','b-a884782eb3ff01de2d414712c01fd7af','b-1396c5081264cf6fdb3e61ecbf8beb27','b-c865717c48615ae3e48c3de42bfe471d','b-016f77ae2833a0f3ba98f97759eb3598','b-365ec07d7ee9f7195248650282110c1f','b-7ef8ccd97b9958840a9118bea7abd33b','b-b7b515e7496f7ac523cd74289a6c6d0d','b-332e2d9d0c8849dc1d367535ceec4759','b-03b42500c4caebe2fa17e5eb4ceb2e03','b-01bd486f792eac9041201ac66906e097','b-04adafb265b961ff188781bc6058e5e0','b-6018ef929e9e5c15f947ac647ec2094e','b-109e6d1dd28b69b607cfb803d5aafc99','b-18fd8b71383ac52acc951a901709a03d','b-4e35c15c3a50a53edda8f7f2679c9e82','b-5a533f6337fa0d6f671363c66e17e787') AND NOT EXISTS(SELECT 1 FROM entity_parameter_values v WHERE v.entity_id=obj AND v.parameter_id=p.id)) THEN RAISE EXCEPTION 'R5 balance is incomplete' USING ERRCODE='23514'; END IF; IF EXISTS(SELECT 1 FROM entity_parameter_values v JOIN entity_parameters p ON p.id=v.parameter_id WHERE v.entity_id=obj AND p.code IN('b-85e68addd7ab15785bf71d567cce71ee','b-3b76763d0b8c898af75bf3eb4ebdc991','b-ac42f13ce036302acdecf7066ff2bd7c','b-9c4fd80c3b3a24c99eb7841928903cfb','b-8c3a41b593d070809feb74df206a4134','b-8a9cbd124b2d1f97ed6fa505af229a17','b-59e3571c09c659912e5854b94aa32bf7','b-10f3eb95d20377431047c08ae546c0c1','b-a0ad7fcffe8ac9a5de33b52d40be19cf','b-a884782eb3ff01de2d414712c01fd7af','b-1396c5081264cf6fdb3e61ecbf8beb27','b-c865717c48615ae3e48c3de42bfe471d','b-016f77ae2833a0f3ba98f97759eb3598','b-365ec07d7ee9f7195248650282110c1f','b-7ef8ccd97b9958840a9118bea7abd33b','b-b7b515e7496f7ac523cd74289a6c6d0d','b-6018ef929e9e5c15f947ac647ec2094e','b-109e6d1dd28b69b607cfb803d5aafc99','b-18fd8b71383ac52acc951a901709a03d') AND v.value_decimal<>trunc(v.value_decimal)) THEN RAISE EXCEPTION 'R5 money and rates must be exact integers' USING ERRCODE='23514'; END IF; IF mod(balance_number(obj,'forge.productions.apprentice.baseCostGoldMilli'),1000)<>0 OR mod(balance_number(obj,'forge.productions.smelter.baseCostGoldMilli'),1000)<>0 OR mod(balance_number(obj,'forge.productions.press.baseCostGoldMilli'),1000)<>0 OR mod(balance_number(obj,'forge.productions.alchemy.baseCostGoldMilli'),1000)<>0 THEN RAISE EXCEPTION 'Production base prices require whole gold' USING ERRCODE='23514'; END IF; END IF; ELSIF obj='ca5b0000-0000-5000-a000-000000000004' THEN IF NOT EXISTS(SELECT 1 FROM entity_parameter_values a JOIN entity_parameter_values s ON s.entity_id=a.value_reference JOIN entity_parameters p ON p.id=s.parameter_id WHERE a.entity_id=obj AND p.code='schema-version' AND s.value_text='runner-balance.2') THEN RAISE EXCEPTION 'Current balance requires R5 schema' USING ERRCODE='23514'; END IF; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER forge_validate_balance AFTER INSERT OR UPDATE OR DELETE ON entities DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION forge_validate_balance();
CREATE CONSTRAINT TRIGGER forge_validate_balance AFTER INSERT OR UPDATE OR DELETE ON entity_parameter_values DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION forge_validate_balance();
CREATE FUNCTION forge_protect_metadata() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE typ uuid; BEGIN IF TG_TABLE_NAME='entity_types' THEN typ:=OLD.id; ELSE IF TG_OP='DELETE' THEN typ:=OLD.entity_type_id; ELSE typ:=NEW.entity_type_id; END IF; END IF; IF typ='ca5f0000-0000-5000-a000-000000000001' AND EXISTS(SELECT 1 FROM entities WHERE entity_type_id=typ AND state='active') THEN RAISE EXCEPTION 'Live workshop metadata is immutable' USING ERRCODE='23514'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
CREATE TRIGGER forge_protect_metadata BEFORE INSERT OR UPDATE OR DELETE ON entity_parameters FOR EACH ROW EXECUTE FUNCTION forge_protect_metadata();
CREATE TRIGGER forge_protect_metadata BEFORE UPDATE OR DELETE ON entity_types FOR EACH ROW EXECUTE FUNCTION forge_protect_metadata();
REVOKE ALL ON FUNCTION forge_fence_writer(),forge_validate_balance(),forge_protect_metadata() FROM PUBLIC;
